-- Seed 060: plain-language explanations of tests for My Chart
-- Subsystem: Patient Portal (My Chart Phase 2). One row per analyte or imaging study,
-- shown under the result so a patient can read what the test is for. The wording is
-- deliberately plain, says what a high or low result can mean, and never diagnoses --
-- every explanation ends up next to the standing note that a result outside the usual
-- range is common and is read by the doctor alongside everything else.
--
-- Idempotency: INSERT IGNORE against uq_portal_explanation (kind, name), so re-running
-- changes nothing and leaves wording the hospital has since edited alone.
--
-- Names match the lab's analytes (procedure_order_configs, tier 'discrete_result') and
-- the imaging studies' identifying_code, so they line up with what a result row carries.
-- `source` names where the wording came from, which the screen shows to the admin.

SET NAMES utf8mb4;

INSERT IGNORE INTO `portal_test_explanations`
    (`kind`, `code`, `name`, `what_it_measures`, `why_ordered`, `high_means`, `low_means`, `source`, `is_active`, `created_at`)
VALUES
-- ---------------- blood count ----------------
('lab', NULL, 'Hemoglobin', 'The protein in your red blood cells that carries oxygen around your body.', 'Part of a blood count, to look for anaemia, bleeding or how well treatment is working.', 'Can happen with dehydration, smoking, lung conditions, or living at altitude.', 'Is called anaemia. Common causes are low iron, blood loss, pregnancy and long-term illness.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Hematocrit', 'How much of your blood is made up of red blood cells, as a percentage.', 'Usually read together with haemoglobin, to look for anaemia or dehydration.', 'Often goes with dehydration, or with a higher number of red cells.', 'Usually means anaemia, the same causes as a low haemoglobin.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'RBC count', 'The number of red blood cells in your blood.', 'Part of a blood count, to help explain anaemia or an unusually thick blood picture.', 'Can happen with dehydration or some lung and bone marrow conditions.', 'Goes with anaemia, from bleeding, low iron or vitamins, or long-term illness.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'WBC count', 'The number of white blood cells, which fight infection.', 'To look for infection or inflammation, and to follow treatment that affects the bone marrow.', 'Often means your body is fighting an infection or inflammation; some medicines also raise it.', 'Can follow a viral illness or some medicines, and can mean less protection from infection.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Platelet count', 'The number of platelets, the small cells that help your blood to clot.', 'To check bleeding or bruising, and before an operation or certain medicines.', 'Can follow infection, inflammation, bleeding or iron deficiency.', 'Can mean easier bruising or bleeding; dengue, some infections and some medicines lower it.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'MCV', 'The average size of your red blood cells.', 'To work out the cause of anaemia -- small cells and large cells point to different causes.', 'Large cells can go with low vitamin B12 or folate, thyroid problems or alcohol.', 'Small cells most often go with low iron, or with an inherited condition such as thalassaemia.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Neutrophils', 'The share of your white cells that are neutrophils, the first to respond to bacteria.', 'Read with the white cell count when infection is suspected.', 'Often points to a bacterial infection or to inflammation and stress.', 'Means less protection from bacterial infection; some medicines and viral illnesses lower it.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Lymphocytes', 'The share of your white cells that are lymphocytes, which deal with viruses.', 'Read with the white cell count, often when a viral illness is suspected.', 'Common during and after viral infections.', 'Can follow a recent infection, steroids, or stress on the body.', 'Hospital laboratory', 1, NOW()),

-- ---------------- kidneys, salts and sugar ----------------
('lab', NULL, 'Sodium', 'A salt in your blood that holds the right amount of water in your body.', 'To check your body water and salts, especially with vomiting, diarrhoea or water tablets.', 'Usually means too little water in the body, from dehydration or not drinking enough.', 'Can come from too much fluid, water tablets, or some hormone and heart conditions.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Potassium', 'A salt that keeps your muscles and heartbeat working properly.', 'To check kidney function and the effect of medicines such as water tablets.', 'Needs attention because it can affect the heartbeat; kidney problems and some medicines raise it.', 'Can cause muscle weakness and cramps; vomiting, diarrhoea and water tablets lower it.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Chloride', 'A salt that works with sodium to balance the fluid in your body.', 'Read with the other salts to understand your body fluid balance.', 'Usually goes with dehydration or with the other salts being high.', 'Often follows vomiting or long-term breathing problems.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Bicarbonate', 'How much acid-buffering there is in your blood.', 'To check whether your blood is too acidic or too alkaline, often alongside kidney and lung problems.', 'Can follow vomiting or long-standing lung disease.', 'Can mean the blood is too acidic, from infection, uncontrolled diabetes or kidney problems.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'BUN', 'A waste product from protein that your kidneys clear out of the blood.', 'To check how well your kidneys are working, with creatinine.', 'Can mean dehydration, a high-protein intake, bleeding in the gut, or reduced kidney function.', 'Usually not a problem; it can go with a low-protein diet, pregnancy or liver disease.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Creatinine', 'A waste product from muscle that your kidneys remove.', 'The main everyday check of how well your kidneys are working.', 'Suggests the kidneys are not clearing waste as well as usual; dehydration and some medicines also raise it.', 'Is usually harmless and can simply reflect less muscle, or pregnancy.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Glucose', 'The amount of sugar in your blood at the moment the sample was taken.', 'To look for diabetes, to follow its treatment, or to explain feeling unwell.', 'Can mean diabetes or a stress response to illness; whether you had eaten matters.', 'Can cause shakiness, sweating and confusion, and matters most for people on diabetes treatment.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'HbA1c', 'Your average blood sugar over the past two to three months.', 'To diagnose diabetes and to see how well it is controlled over time.', 'Means blood sugar has been high on average; your doctor will discuss treatment.', 'Is usually good control, but can be low with anaemia or after blood loss.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Calcium', 'The calcium in your blood, which your bones, muscles and nerves need.', 'To check bones, the parathyroid glands and kidney problems.', 'Can come from the parathyroid glands, some cancers, or too much vitamin D.', 'Can cause tingling and cramps; low vitamin D and kidney problems are common causes.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Magnesium', 'A mineral your muscles, nerves and heart rhythm depend on.', 'Often checked with potassium and calcium, or when the heart rhythm is irregular.', 'Is uncommon and usually relates to kidney problems or supplements.', 'Can cause cramps and an irregular heartbeat; alcohol, diarrhoea and some medicines lower it.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Phosphorus', 'A mineral that works with calcium for your bones and energy.', 'Checked in kidney disease and with calcium problems.', 'Is common in kidney disease.', 'Can follow poor nutrition, alcohol use or some medicines.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Uric acid', 'A waste product that can form crystals in the joints.', 'Usually to look into gout, kidney stones or kidney function.', 'Can go with gout, kidney problems or a diet rich in meat and seafood.', 'Is rarely a problem on its own.', 'Hospital laboratory', 1, NOW()),

-- ---------------- liver ----------------
('lab', NULL, 'Total protein', 'All the protein in your blood together.', 'A general check of nutrition, the liver and the kidneys.', 'Can follow dehydration or long-standing inflammation.', 'Can go with poor nutrition, liver disease or protein lost through the kidneys or gut.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Albumin', 'The main protein your liver makes, which keeps fluid inside the blood vessels.', 'To check the liver and your nutrition, and to explain swelling.', 'Usually means dehydration rather than a problem with the liver.', 'Can go with liver disease, poor nutrition, long illness, or protein lost in the urine.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Total bilirubin', 'A yellow substance made when old red blood cells break down; the liver clears it.', 'To look into yellow eyes or skin, gallstones and liver problems.', 'Causes yellowing of the eyes and skin, from liver problems, gallstones or faster red cell breakdown.', 'Is not a problem.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Direct bilirubin', 'The part of the bilirubin the liver has already processed.', 'Read with total bilirubin to tell liver problems from blocked bile ducts.', 'Points towards blocked bile flow or liver cell damage.', 'Is not a problem.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'ALT', 'An enzyme found mainly in liver cells.', 'The usual check for irritation or damage of the liver.', 'Means liver cells are irritated -- from fatty liver, alcohol, medicines or a viral infection.', 'Is not a problem.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'AST', 'An enzyme found in the liver and also in muscle.', 'Read with ALT to look at the liver; hard exercise and muscle injury raise it too.', 'Can mean the liver is irritated, or simply that muscle has been strained.', 'Is not a problem.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'ALP', 'An enzyme from the bile ducts and the bones.', 'To look into blocked bile flow, and bone problems.', 'Can mean bile is not draining freely, or active bone turnover; it is normally higher in children and in pregnancy.', 'Is uncommon and rarely a problem.', 'Hospital laboratory', 1, NOW()),

-- ---------------- heart, clotting and inflammation ----------------
('lab', NULL, 'Troponin I', 'A protein released when heart muscle is strained or damaged.', 'The main blood test when chest pain might be coming from the heart.', 'Means heart muscle has been under strain; it is read with your symptoms and the ECG.', 'Is the expected result and makes a heart attack much less likely.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'CK-MB', 'An enzyme that comes mostly from heart muscle.', 'Sometimes used with troponin when heart muscle damage is suspected.', 'Can point to heart muscle damage, though muscle injury raises it too.', 'Is the expected result.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'NT-proBNP', 'A hormone the heart releases when it is stretched or working too hard.', 'To help tell heart failure from other causes of breathlessness.', 'Suggests the heart is under strain, which fits with heart failure.', 'Makes heart failure much less likely as the cause of breathlessness.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'D-dimer', 'A fragment left behind when a blood clot breaks down.', 'To help rule out a clot in the leg or the lungs.', 'Only means a clot cannot be ruled out by this test alone -- a scan is usually the next step. Infection, surgery and pregnancy raise it too.', 'Makes a clot very unlikely.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'INR', 'How long your blood takes to clot, compared with normal.', 'To follow blood-thinning treatment with warfarin, and to check the liver.', 'Means the blood is slower to clot, so there is more risk of bleeding.', 'Means the blood clots faster than the target, so there is less protection from clots.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Prothrombin time', 'How long one part of the clotting process takes.', 'Read with INR, before procedures and in liver disease.', 'Means slower clotting, from blood thinners, liver disease or low vitamin K.', 'Is rarely a problem.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'aPTT', 'How long another part of the clotting process takes.', 'Used with heparin treatment and to look into bleeding problems.', 'Means slower clotting -- expected on heparin, otherwise it needs looking into.', 'Is rarely a problem.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'CRP', 'A protein your liver makes when there is inflammation anywhere in the body.', 'To look for infection or inflammation and to follow how it settles.', 'Means inflammation somewhere -- it says how much, not where or why.', 'Means little inflammation at the moment.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'ESR', 'How quickly red cells settle in a tube, which rises with inflammation.', 'An older, slower measure of inflammation, used for some long-term conditions.', 'Means inflammation somewhere; it rises and falls more slowly than CRP.', 'Is normal.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Procalcitonin', 'A substance that rises mainly with bacterial infection.', 'To help decide whether an infection is bacterial and whether antibiotics are needed.', 'Points towards a bacterial infection.', 'Makes a serious bacterial infection less likely.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Lactate', 'A substance that builds up when tissues are not getting enough oxygen.', 'Used when someone is seriously unwell, to judge how the body is coping.', 'Means the body is under strain and needs prompt attention.', 'Is the expected result.', 'Hospital laboratory', 1, NOW()),

-- ---------------- thyroid and fats ----------------
('lab', NULL, 'TSH', 'The hormone from your brain that tells the thyroid how much to work.', 'The first check of thyroid function.', 'Usually means an underactive thyroid -- the brain is pushing a gland that is not keeping up.', 'Usually means an overactive thyroid, or too much thyroid medicine.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Free T4', 'The active thyroid hormone circulating in your blood.', 'Read with TSH to confirm how the thyroid is working.', 'Goes with an overactive thyroid.', 'Goes with an underactive thyroid.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Total cholesterol', 'All the cholesterol in your blood together.', 'To judge the risk of heart disease and stroke over the coming years.', 'Raises long-term risk to the heart and blood vessels; diet, exercise and medicines can lower it.', 'Is usually fine.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'LDL cholesterol', 'The cholesterol that can build up in artery walls, often called "bad" cholesterol.', 'The number treatment usually aims at when lowering heart risk.', 'Raises the risk of heart attack and stroke over time.', 'Is good for your heart risk.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'HDL cholesterol', 'The cholesterol that carries fat away from the arteries, often called "good" cholesterol.', 'Read with the rest of the fats to judge heart risk.', 'Is protective -- higher is better here.', 'Adds to heart risk; exercise and stopping smoking raise it.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Triglycerides', 'Another kind of fat in your blood, strongly affected by recent food and alcohol.', 'Part of the fats check for heart risk, and for the pancreas when very high.', 'Adds to heart risk, and when very high can irritate the pancreas. Fasting matters for this one.', 'Is not a problem.', 'Hospital laboratory', 1, NOW()),

-- ---------------- urine and infection ----------------
('lab', NULL, 'Urine protein', 'Protein that has leaked into your urine.', 'To check the kidneys, especially with diabetes, high blood pressure or in pregnancy.', 'Can be an early sign that the kidneys are leaking protein and is usually repeated.', 'Is the expected result.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Urine leukocyte esterase', 'A sign of white blood cells in the urine.', 'Part of the urine test when a urine infection is suspected.', 'Suggests infection or inflammation in the urinary tract.', 'Makes a urine infection less likely.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Urine nitrite', 'A substance some bacteria make in urine.', 'Part of the urine test for infection.', 'Points strongly to a urine infection with common bacteria.', 'Does not rule out infection on its own.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Urine culture', 'Growing any bacteria from your urine in the laboratory, and testing which antibiotics work.', 'To confirm a urine infection and choose the right antibiotic.', 'A growth means bacteria were found; the report names them and the antibiotics that work.', 'No growth means no infection was found in this sample.', 'Hospital laboratory', 1, NOW()),
('lab', NULL, 'Blood culture', 'Growing any bacteria from your blood in the laboratory.', 'When a serious infection in the bloodstream is suspected.', 'A growth means bacteria were found in the blood and need treatment.', 'No growth is the result everyone hopes for. It takes a few days to be sure.', 'Hospital laboratory', 1, NOW()),

-- ---------------- imaging studies ----------------
('imaging', 'CXR', 'Chest X-ray (PA)', 'A picture of your lungs, heart and ribs made with a small dose of X-rays.', 'For cough, fever, breathlessness or chest pain, and before some operations.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'CXRPAL', 'Chest X-ray (PA and lateral)', 'Two pictures of the chest from different directions, which show more than one view alone.', 'When a side view adds something, for example to place a shadow seen on the first picture.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'AXR', 'Abdominal X-ray (KUB)', 'A picture of your abdomen, showing the bowel gas pattern and some stones.', 'For abdominal pain, constipation or a suspected blockage.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'USWA', 'Ultrasound: whole abdomen', 'Pictures made with sound waves, with no X-rays at all.', 'To look at the liver, gallbladder, kidneys, spleen and pancreas, often for pain.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'USHBT', 'Ultrasound: hepatobiliary tree (liver, gallbladder)', 'Sound-wave pictures of the liver, gallbladder and bile ducts.', 'Usually to look for gallstones or to check the liver.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'USKUB', 'Ultrasound: kidneys, ureters and bladder (KUB)', 'Sound-wave pictures of the kidneys and bladder.', 'For kidney stones, urine infections or a change in kidney tests.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'USOB', 'Obstetric ultrasound (pregnancy)', 'Sound-wave pictures of the baby and the womb. It uses no X-rays.', 'To check the baby''s growth, position and wellbeing during pregnancy.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'CTHEAD', 'CT head (plain)', 'A detailed set of X-ray pictures of the brain and skull, built up by a computer.', 'After a head injury, or for stroke symptoms, severe headache or confusion.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'CTAP', 'CT abdomen and pelvis with contrast', 'Detailed X-ray pictures of the abdomen and pelvis, with a dye given to show the organs and blood vessels more clearly.', 'For abdominal pain that needs a closer look than an ultrasound can give.', NULL, NULL, 'Hospital radiology department', 1, NOW()),
('imaging', 'MRBRAIN', 'MRI brain (plain)', 'Pictures of the brain made with a strong magnet and radio waves, with no X-rays.', 'For headaches, fits, weakness or numbness that need detailed pictures of the brain.', NULL, NULL, 'Hospital radiology department', 1, NOW());
